class Leader:
    def __init__(self, epoch):
        self.epoch = epoch
        self.counter = 0
        self.quorum_size = 2  # 3-node ensemble, including self

    def propose(self, txn, followers):
        self.counter += 1
        zxid = (self.epoch << 32) | self.counter
        # FIFO send: follower that sees zxid N has seen all < N.
        for f in followers:
            f.receive_propose(zxid, txn)  # follower: fsync to txn log, then ACK
        acks = 1  # leader counts itself after local fsync
        for f in followers:
            if f.ack(zxid):  # blocks until fsync done on follower
                acks += 1
            if acks >= self.quorum_size:
                break
        if acks >= self.quorum_size:
            self.commit(zxid)  # apply in order, then broadcast COMMIT
            return zxid
        raise QuorumLost("minority partition: cannot commit, step down")

class Follower:
    def apply_commit(self, zxid):
        # Must apply strictly in zxid order. Gap -> wait, do not skip.
        assert zxid == self.last_delivered + 1, "prefix violation: stall, request sync"
        self.state_machine.apply(zxid)
        self.last_delivered = zxid
